<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Device; use App\Models\User; use App\Support\ApiResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Illuminate\Support\Str;
class AuthController extends Controller {
 public function login(Request $r){$v=$r->validate(['email'=>'required|email','password'=>'required|string','device_uuid'=>'required|string|max:191','device_model'=>'nullable|string|max:191','manufacturer'=>'nullable|string|max:191','android_version'=>'nullable|string|max:50','app_version'=>'nullable|string|max:50','push_token'=>'nullable|string|max:1000']); $install=$r->header('X-Installation-UUID'); if(!$install)return ApiResponse::error('X-Installation-UUID is required.',422,null,'INSTALLATION_UUID_REQUIRED'); $u=User::with(['tenant','salesman'])->where('email',$v['email'])->first(); if(!$u||!Hash::check($v['password'],$u->password)||!$u->is_active)return ApiResponse::error('Invalid credentials.',422,['email'=>['The provided credentials are incorrect.']],'INVALID_CREDENTIALS'); if(!$u->salesman)return ApiResponse::error('No salesman profile is linked to this user.',422,null,'SALESMAN_REQUIRED'); $existing=Device::where('tenant_id',$u->tenant_id)->where('user_id',$u->id)->where('installation_uuid',$install)->first(); if($existing?->revoked_at)return ApiResponse::error('This device has been revoked.',403,null,'DEVICE_REVOKED'); $other=Device::where('salesman_id',$u->salesman->id)->where('is_active',true)->whereNull('revoked_at')->when($existing,fn($q)=>$q->whereKeyNot($existing->id))->first(); if($other)return ApiResponse::error('Only one active device is allowed for this salesman.',422,null,'DEVICE_LIMIT_REACHED'); $device=Device::updateOrCreate(['tenant_id'=>$u->tenant_id,'user_id'=>$u->id,'installation_uuid'=>$install],['uuid'=>$existing?->uuid??(string)Str::uuid(),'salesman_id'=>$u->salesman->id,'device_uuid'=>$v['device_uuid'],'device_model'=>$v['device_model']??null,'manufacturer'=>$v['manufacturer']??null,'android_version'=>$v['android_version']??null,'app_version'=>$v['app_version']??null,'push_token'=>$v['push_token']??null,'is_active'=>true,'registered_at'=>$existing?->registered_at??now(),'last_seen_at'=>now(),'revoked_at'=>null]); $u->tokens()->where('name','mobile-'.$device->uuid)->delete(); $token=$u->createToken('mobile-'.$device->uuid)->plainTextToken; return ApiResponse::success(['token'=>$token,'user'=>['id'=>$u->uuid,'name'=>$u->name,'email'=>$u->email,'role'=>$u->role],'tenant'=>['id'=>$u->tenant->uuid,'name'=>$u->tenant->name,'timezone'=>$u->tenant->timezone],'permissions'=>['attendance.view','attendance.manage','gps.upload'],'device'=>['id'=>$device->uuid,'device_uuid'=>$device->device_uuid,'installation_uuid'=>$device->installation_uuid]]); }
 public function logout(Request $r){$r->user()?->currentAccessToken()?->delete(); return ApiResponse::success(['logged_out'=>true]);}
}
